/**
 * Tool videos — GENERATED by scripts/video/build.mjs. Do not edit by hand.
 *
 * Keyed by calculator slug. A tool with no entry renders no video; the page must not invent one.
 * Regenerate with `npm run video:build` (or `npm run video:build -- <slug>`).
 */
export interface ToolVideoEntry {
	src: string;
	poster: string;
	width: number;
	height: number;
	durationSec: number;
	captions?: string;
}

export const TOOL_VIDEOS: Record<string, ToolVideoEntry> = {
	'decision-intelligence': {
		src: '/media/tool-videos/decision-intelligence.mp4',
		poster: '/media/tool-videos/decision-intelligence-poster.jpg',
		width: 1280,
		height: 720,
		durationSec: 19.50,
		captions: '/media/tool-videos/decision-intelligence.vtt'
	},
	'gpu-compute': {
		src: '/media/tool-videos/gpu-compute.mp4',
		poster: '/media/tool-videos/gpu-compute-poster.jpg',
		width: 1280,
		height: 720,
		durationSec: 21.50,
		captions: '/media/tool-videos/gpu-compute.vtt'
	}
};

export function getToolVideo(slug: string): ToolVideoEntry | null {
	return TOOL_VIDEOS[slug] ?? null;
}
